(()=>{
function attach(area){if(area.dataset.formatting)return;area.dataset.formatting='1';const bar=document.createElement('div');bar.className='format-toolbar';bar.setAttribute('role','group');bar.setAttribute('aria-label','Text formatting');const preview=document.createElement('div');preview.className='formatted-preview';preview.hidden=true;preview.setAttribute('aria-label','Learner text preview');
const help=document.createElement('small');help.textContent='Use **bold**, *italic*, <sup>superscript</sup> or <sub>subscript</sub>. Line breaks are preserved. Preview shows the learner formatting.';
for(const [name,mark] of [['Bold','**'],['Italic','*'],['x²','<sup>'],['x₂','<sub>'],['Bullet list','- '],['Numbered list','1. ']]){const b=document.createElement('button');b.type='button';b.textContent=name;b.className='secondary';b.onclick=()=>{const start=area.selectionStart,end=area.selectionEnd;const selected=area.value.slice(start,end)||'text';const block=mark.endsWith(' ');const content=block?selected.split('\n').map((s,i)=>(mark==='1. '?(i+1)+'. ':mark)+s).join('\n'):mark+selected+(mark==='<sup>'?'</sup>':mark==='<sub>'?'</sub>':mark);area.setRangeText((block&&start>0&&area.value[start-1]!=='\n'?'\n':'')+content,start,end,'select');area.dispatchEvent(new Event('input',{bubbles:true}));area.focus();};bar.append(b);}
const toggle=document.createElement('button');toggle.type='button';toggle.className='secondary';toggle.textContent='Show learner preview';toggle.setAttribute('aria-expanded','false');toggle.onclick=()=>{preview.hidden=!preview.hidden;toggle.textContent=preview.hidden?'Show learner preview':'Hide preview';toggle.setAttribute('aria-expanded',String(!preview.hidden));preview.innerHTML=RichText.render(area.value);};bar.append(toggle);area.before(bar);area.after(help,preview);document.addEventListener('change',()=>setTimeout(()=>{if(!preview.hidden)preview.innerHTML=RichText.render(area.value)},0));area.addEventListener('input',()=>{preview.innerHTML=RichText.render(area.value)});if(document.getElementById('editor-title'))new MutationObserver(()=>{if(!preview.hidden)preview.innerHTML=RichText.render(area.value)}).observe(document.getElementById('editor-title'),{childList:true});}
for(const id of ['text','explanation','additional-findings','case-history','case-examination','case-laboratory']){const area=document.getElementById(id);if(area)attach(area);}
window.attachTextFormatting=attach;
function choices(){document.querySelectorAll('[id^=choice-]').forEach(a=>{if(!a.dataset.formatting&&a.matches('input[type=text],textarea')){if(a.tagName==='INPUT'){const wrap=document.createElement('div');a.before(wrap);wrap.append(a);}attach(a);}})}
choices();if(document.getElementById('choices'))new MutationObserver(choices).observe(document.getElementById('choices'),{childList:true});
const style=document.createElement('style');style.textContent='.format-toolbar{display:flex;flex-wrap:wrap;gap:6px;margin:8px 0}.format-toolbar button{padding:6px 10px;font-size:13px}.formatted-preview{font-weight:normal;padding:18px;border:1px solid #ccd7e8;border-radius:8px;margin:12px 0;background:#f7f9ff;line-height:1.65}.formatted-preview[hidden]{display:none}.formatted-preview ul,.formatted-preview ol{padding-left:24px}';document.head.append(style);
})();
